// Captured header CRC per target (with the captured sync/startup bits);
// used only by the self-test.
static const uint16_t dde_emu_static_captured_hcrc[DDE_EMU_N_STATIC] = {0x44D, 0x45E, 0x5AB, 0x683};

// E2E groups: {target index, cycle mod 4, crc byte, span end (incl), K}
// CRC byte = CRC8_0x1D(payload[crc+1 .. end]) ^ K; payload[crc+1] low nibble = alive counter.
#define DDE_EMU_N_E2E 9
